using System.Net;
using System.Text.Json;
using ForensicEdu.Mobile.Core.Services;
using ForensicEdu.Mobile.Core.Models;
using ForensicEdu.Mobile.Core.ViewModels;
var checks=0;
void Check(bool ok,string title){if(!ok)throw new Exception(title);checks++;Console.WriteLine("PASS "+title);}
var tokens=new Tokens{Value="test-token"};var handler=new Handler();using var http=new HttpClient(handler){BaseAddress=new Uri("http://10.0.2.2:5000/api/")};var api=new AcademyApi(http,tokens);
handler.Reply=(_,_)=>new(HttpStatusCode.OK){Content=new StringContent("[]")};await api.GetAsync<List<Course>>("courses",false);Check(handler.Authorization==null,"Public catalog does not send session credentials");await api.GetAsync<List<Course>>("student/enrollments");Check(handler.Authorization=="Bearer test-token","Private endpoints authenticate");
try{await api.GetAsync<object>("https://example.invalid/api");throw new Exception("accepted");}catch(ArgumentException){Check(true,"Reject external request URLs");}
Check(api.PublicImage("ftp://10.0.2.2:5000/file")==null,"Reject non-HTTP image schemes");Check(api.PublicImage("http://example.invalid/x")==null,"Reject insecure external image URLs");
var expired=false;api.AuthenticationExpired+=()=>expired=true;handler.Reply=(_,_)=>new(HttpStatusCode.Unauthorized){Content=new StringContent("{\"message\":\"expired\"}")};try{await api.GetAsync<object>("auth/me");}catch(ApiException e){Check(e.Status==401&&tokens.Value==null&&expired,"401 clears stored session and notifies app");}
var clock=new Clock();handler.Reply=(req,_)=>{if(req.RequestUri!.AbsolutePath.EndsWith("/start"))return Json(new{ id="attempt",attemptNumber=1,serverTime=clock.Now.AddHours(2),expiresAt=clock.Now.AddHours(2).AddMinutes(10),questions=new[]{new{id="q",question="Question",options=new[]{"A","B"}}},savedAnswers=new Dictionary<string,int>{{"q",1}}});if(req.RequestUri.AbsolutePath.EndsWith("/submit"))return Json(new{score=20,approved=true,message="ok"});return new(HttpStatusCode.NoContent);};
var exam=new ExamViewModel(api,clock);await exam.StartAsync("enrollment");Check(exam.RemainingSeconds==600,"Exam uses server clock despite device offset");Check(exam.Answers["q"]==1,"Resume restores saved answers");clock.Now=clock.Now.AddSeconds(25);Check(exam.RemainingSeconds==575,"Deadline advances with elapsed time");await exam.ChooseAsync("q",0);Check(handler.LastBody!.Contains("\"q\":0"),"Answers saved to backend");clock.Now=clock.Now.AddMinutes(20);Check(exam.RemainingSeconds==0,"Timer clamps at deadline");var before=handler.Calls;await Task.WhenAll(exam.SubmitAsync("enrollment","user"),exam.SubmitAsync("enrollment","user"));Check(exam.Result?.Approved==true&&handler.Calls==before+1,"Concurrent expiry and submit sends only once");
var account=new AccountSession(api,tokens);
handler.Reply=(_,_)=>Json(new{requiresRegistration=true,email="student@example.invalid",nombres="Prueba",apellidos="Alumno"});
var googleRegistration=await account.GoogleAsync("google-test-credential");Check(googleRegistration.RequiresRegistration&&tokens.Value==null&&account.User==null,"Google registration does not invent a logged-in session");Check(handler.Authorization==null,"Google credential exchange does not send a stale academy JWT");
handler.Reply=(_,_)=>Json(new{requiresLinkPassword=true,email="student@example.invalid"});var link=await account.GoogleAsync("google-test-credential");Check(link.RequiresLinkPassword&&tokens.Value==null,"Existing local account requires password confirmation");
handler.Reply=(request,_)=>request.RequestUri!.AbsolutePath.EndsWith("/auth/me")?Json(new{id="google-user",fullName="Alumno",email="student@example.invalid"}):Json(new{token="academy-google-session"});await account.GoogleAsync("google-test-credential",linkPassword:"test-link-password");Check(tokens.Value=="academy-google-session"&&account.User?.Id=="google-user","Google success stores academy token and loads authenticated profile");
await account.LogoutAsync();handler.Reply=(request,_)=>request.RequestUri!.AbsolutePath.EndsWith("/auth/me")?new(HttpStatusCode.Forbidden){Content=new StringContent("{}")}:Json(new{token="invalid-profile-session"});try{await account.GoogleAsync("google-test-credential");}catch(ApiException){Check(tokens.Value==null&&account.User==null,"Failed Google profile clears the partial session");}
Console.WriteLine($"{checks} mobile checks passed.");
static HttpResponseMessage Json(object data)=>new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(data,AcademyApi.Json))};
sealed class Tokens:ITokenStore{public string? Value;public Task<string?> ReadAsync()=>Task.FromResult(Value);public Task WriteAsync(string token){Value=token;return Task.CompletedTask;}public Task ClearAsync(){Value=null;return Task.CompletedTask;}}
sealed class Handler:HttpMessageHandler{public Func<HttpRequestMessage,CancellationToken,HttpResponseMessage> Reply=(_,_)=>new(HttpStatusCode.OK);public string? Authorization;public string? LastBody;public int Calls;protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;Authorization=request.Headers.Authorization?.ToString();LastBody=request.Content==null?null:await request.Content.ReadAsStringAsync(ct);return Reply(request,ct);}}
sealed class Clock:TimeProvider{public DateTimeOffset Now=DateTimeOffset.Parse("2026-10-30T12:00:00Z");public override DateTimeOffset GetUtcNow()=>Now;}
